import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"桃源行","description":"","frontmatter":{"title":"桃源行","date":"2026-11-27T00:00:00.000Z","seq":10,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 乐府》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"王维","source_book":"唐诗三百首","prev":{"text":"老将行","link":"/blogs/唐诗三百首·乐府/老将行.html"},"next":{"text":"清平调·云想衣裳花想容","link":"/blogs/唐诗三百首·乐府/清平调·云想衣裳花想容.html"}},"headers":[],"relativePath":"blogs/唐诗三百首·乐府/桃源行.md","filePath":"blogs/唐诗三百首·乐府/桃源行.md"}'),o={name:"blogs/唐诗三百首·乐府/桃源行.md"};function l(n,a,c,m,r,_){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="桃源行" tabindex="-1">桃源行 <a class="header-anchor" href="#桃源行" aria-label="Permalink to &quot;桃源行&quot;">​</a></h1><p class="poem-meta">唐 · 王维　·　乐府</p><div class="poem"><p class="poem-stanza">渔舟逐水爱山春，两岸桃花夹古津。</p><p class="poem-stanza">坐看红树不知远，行尽青溪不见人。</p><p class="poem-stanza">山口潜行始隈隩，山开旷望旋平陆。</p><p class="poem-stanza">遥看一处攒云树，近入千家散花竹。</p><p class="poem-stanza">樵客初传汉姓名，居人未改秦衣服。</p><p class="poem-stanza">居人共住武陵源，还从物外起田园。</p><p class="poem-stanza">月明松下房栊静，日出云中鸡犬喧。</p><p class="poem-stanza">惊闻俗客争来集，竞引还家问都邑。</p><p class="poem-stanza">平明闾巷扫花开，薄暮渔樵乘水入。</p><p class="poem-stanza">初因避地去人间，及至成仙遂不还。</p><p class="poem-stanza">峡里谁知有人事，世中遥望空云山。</p><p class="poem-stanza">不疑灵境难闻见，尘心未尽思乡县。</p><p class="poem-stanza">出洞无论隔山水，辞家终拟长游衍。</p><p class="poem-stanza">自谓经过旧不迷，安知峰壑今来变。</p><p class="poem-stanza">当时只记入山深，青溪几度到云林。</p><p class="poem-stanza">春来遍是桃花水，不辨仙源何处寻。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
